 using StackOverflow.Views.Developer;
 
 namespace StackOverflow.Controllers
@@ -59,5 +62,98 @@ namespace StackOverflow.Controllers
                 return HtmlPlain("Invalidate thanks votes", $"Counted {count} thanks votes (nothing deleted).", false);
             }
         }
+
+        [StackRoute("developer/votes/insert-suspicious", PostToRun = true)]
+        public ActionResult InsertSuspiciousVote()
+        {
+            var post = Current.DB.QuerySingleOrDefault<RandomPostRow>(@"
+SELECT TOP 1 Id, OwnerUserId
+  FROM Posts
+ WHERE OwnerUserId IS NOT NULL
+   AND OwnerUserId > {=REAL_ID_FLOOR}
+ ORDER BY NEWID()", new { Models.User.REAL_ID_FLOOR });
+
+            if (post == null)
+            {
+                return HtmlPlain("Insert suspicious vote", "No suitable post found.", false);
+            }
+
+            var user = Current.DB.QuerySingleOrDefault<RandomUserRow>(@"
+SELECT TOP 1 u.Id
+  FROM Users u
+ WHERE u.Id > {=REAL_ID_FLOOR}
+   AND u.Id <> @ownerUserId
+   AND NOT EXISTS
+   (
+       SELECT 1
+         FROM Posts2Votes v
+        WHERE v.PostId = @postId
+          AND v.UserId = u.Id
+          AND v.VoteTypeId IN ({=UpMod},{=DownMod})
+   )
+ ORDER BY NEWID()", new
+            {
+                Models.User.REAL_ID_FLOOR,
+                ownerUserId = post.OwnerUserId,
+                postId = post.Id,
+                Models.VoteTypeId.UpMod,
+                Models.VoteTypeId.DownMod,
+            });
+
+            if (user == null)
+            {
+                return HtmlPlain("Insert suspicious vote", "No suitable user found.", false);
+            }
+
+            var votes = new List<Posts2Vote>();
+            for (var i = 0; i < 3; i++)
+            {
