+                {
+                    PostId = post.Id,
+                    UserId = user.Id,
+                    VoteTypeId = Models.VoteTypeId.UpMod,
+                    CreationDate = Current.Time.AddSeconds(i),
+                    IPAddress = "127.0.0.1",
+                    TargetUserId = post.OwnerUserId,
+                    ApplicationId = Current.ApplicationId
+                });
+            }
+
+            Current.DB.Posts2Votes.AddRange(votes);
+            Current.DB.SaveChanges();
+
+            var suspiciousVotes = votes.Select(vote => new SuspiciousVote
+            {
+                Posts2VotesId = vote.Id,
+                SuspiciousUserId = user.Id,
+                SuspiciousVoteTypeId = (byte)SuspiciousVoteType.UpVoteChainByUser,
+                CreationDate = Current.Time,
