+                {
+                    Posts2VoteIdInChain = new[] { vote.Id },
+                    UserChain = new[] { user.Id, post.OwnerUserId },
+                    ProxyType = "ManualTest"
+                })
+            }).ToList();
+
+            SuspiciousVotesDetectorRepository.UpsertSuspiciousVotes(suspiciousVotes);
+
+            return HtmlPlain(
+                "Insert suspicious vote",
