+                false);
+        }
+
+        private sealed class RandomPostRow
+        {
+            public int Id { get; set; }
+            public int OwnerUserId { get; set; }
+        }
+
+        private sealed class RandomUserRow
+        {
+            public int Id { get; set; }
+        }
     }
 }
